/* @lc app=leetcode id=2646 lang=kotlin */
class Solution { fun minimumTotalPrice(n: Int, edges: Array<IntArray>, price: IntArray, trips: Array<IntArray>): Int = Array(n) { mutableListOf<Int>() }.also { adj -> edges.forEach { adj[it[0]].add(it[1]).also { _ -> adj[it[1]].add(it[0]) } } }.let { adj -> IntArray(n).also { count -> trips.forEach { trip -> kotlin.DeepRecursiveFunction<Triple<Int, Int, Int>, Boolean> { (u, p, target) -> if (u == target) true.also { count[u]++ } else adj[u].filter { it != p }.any { v -> callRecursive(Triple(v, u, target)).also { if (it) count[u]++ } } }.invoke(Triple(trip[0], -1, trip[1])) } }.let { count -> kotlin.DeepRecursiveFunction<Pair<Int, Int>, Pair<Int, Int>> { (u, p) -> adj[u].filter { it != p }.map { v -> callRecursive(v to u) }.let { res -> (price[u] * count[u] + res.sumOf { Math.min(it.first, it.second) }) to (price[u] * count[u] / 2 + res.sumOf { it.first }) } }.invoke(0 to -1).let { Math.min(it.first, it.second) } } } }